                        throw new IOException("Rebuild failed: " + ne.Message + "; Original message: " + e.Message);
                    }
                }
                try {
                    ReadDocObj();
                }
                catch (Exception ne) {
                    if (rebuilt)
                        throw ne;
                    rebuilt = true;
                    encrypted = false;
                    RebuildXref();
                    lastXref = -1;
                    ReadDocObj();
                }

                strings.Clear();
                ReadPages();
                EliminateSharedStreams();
                RemoveUnusedObjects();
            }
            finally {
                try {
                    tokens.Close();
                }
                catch {
                    // empty on purpose
                }
            }
        }

